<script lang="ts">
 import {languageOverrides} from "./localization";
 import type {Project} from './model';import {projectSchema,uid} from './model';import {monthNext,charges,closePeriod,D,money} from './engine';import {accountOpenInMonth} from './account-lifecycle';import {makeAdministrationDocument,administrationRow,saveAdministrationDocument,rollbackCalculations} from './administration';import {displayPeriod} from './date-format';import {ask} from './storage';import {translator} from './i18n';import {Check,X,ChevronLeft,ChevronRight,Calculator,ListChecks} from "./icons";
 export let project:Project;export let onapply:(p:Project)=>void;export let onclose:()=>void;
 const current=project.settings.period;let step=1,additional=false,previous=false,target=monthNext(current),past=current,selected:string[]=[],error='';$:t=translator(project.settings.language,$languageOverrides);$:accounts=project.accounts.filter(a=>accountOpenInMonth(a,current)&&!project.snapshots.some(s=>s.account_id===a.id&&s.period===current));
 function next(){error='';if(step===1){if(previous&&(!additional||past>=current)){error=t('Выберите прошлый период.','Selectați o perioadă anterioară.');return;}target=additional&&previous?past:monthNext(current);selected=accounts.map(a=>a.id);step=previous?3:2;}else step=3;}
 function calculate(){try{const doc=makeAdministrationDocument(project,'service-charges');doc.rows=selected.map(id=>({...administrationRow(project),account_id:id}));onapply(saveAdministrationDocument(project,doc,true));error='';}catch(e){error=e instanceof Error?e.message:String(e);}}
 async function finish(){try{let next=structuredClone(project);if(target<current){if(!await ask(t('Начисления начиная с выбранного периода будут отменены. Оплаты и исходные показания сохранятся. Продолжить?','Calculele începând cu perioada aleasă vor fi anulate. Plățile și indexurile sursă se păstrează. Continuați?')))return;next=rollbackCalculations(next,target);}else if(!next.closed_periods.includes(current)&&!accounts.length){try{next=closePeriod(next,current);}catch{ /* Advancing without closing preserves an explicit gap in the ledger. */ }}next.settings.period=target;onapply(projectSchema.parse(next));onclose();}catch(e){error=e instanceof Error?e.message:String(e);}}
</script>
<div class="period-wizard">{#if error}<p class="alert error" role="alert">{error}</p>{/if}{#if step===1}<label>{t('Текущий период организации','Perioada curentă a organizației')}<input readonly value={displayPeriod(current,project)}/></label><label>{t('Устанавливается период','Perioada nouă')}<input readonly value={displayPeriod(additional&&previous?past:monthNext(current),project)}/></label><label class="check-row"><input type="checkbox" bind:checked={additional}/>{t('Дополнительно','Suplimentar')}</label>{#if additional}<fieldset><legend>{t('Установка прошлого периода','Setarea unei perioade anterioare')}</legend><label class="check-row"><input type="checkbox" bind:checked={previous}/>{t('Установить прошлый период','Setează o perioadă anterioară')}<input type="month" bind:value={past} disabled={!previous}/></label><p class="danger">{t('При установке прошлого периода все проведённые начисления, включая начисления устанавливаемого периода, будут аннулированы.','La revenire, toate calculele aplicate începând cu perioada aleasă vor fi anulate.')}</p></fieldset>{/if}
{:else if step===2}<h3>{t('Проверка начислений','Verificarea calculelor')}</h3><p>{t('Можно рассчитать выбранные счета или продолжить без расчёта.','Puteți calcula conturile selectate sau continua fără calcul.')}</p><nav><button onclick={()=>selected=accounts.map(a=>a.id)}><ListChecks size={16}/>{t('Выделить все','Selectează toate')}</button><button onclick={()=>selected=[]}><X size={16}/>{t('Снять все','Deselectează toate')}</button><button disabled={!selected.length} onclick={calculate}><Calculator size={16}/>{t('Рассчитать','Calculează')}</button></nav><div class="table-wrap"><table><thead><tr><th></th><th>{t('Лицевой счёт','Cont personal')}</th><th>{t('Ответственный','Titular')}</th><th>{t('Проверка','Verificare')}</th></tr></thead><tbody>{#each accounts as a}<tr><td><input type="checkbox" checked={selected.includes(a.id)} onchange={e=>selected=e.currentTarget.checked?[...selected,a.id]:selected.filter(id=>id!==a.id)}/></td><td>{a.number}</td><td>{a.payer_name}</td><td>{charges(project,a,current).warnings.join('; ')}</td></tr>{/each}</tbody></table></div>
{:else}<h3>{t('Установка расчётного периода','Setarea perioadei de calcul')}</h3><p>{t('Будет установлен период: ','Perioada nouă: ')}{displayPeriod(target,project)}</p>{#if target<current}<p class="danger">{t('Будут отменены начисления за выбранный и последующие месяцы.','Se vor anula calculele lunii selectate și lunilor următoare.')}</p>{:else if accounts.length}<p>{t('Не рассчитано счетов: ','Conturi necalculate: ')}{accounts.length}. {t('Неполная история останется отмеченной в отчётах.','Istoricul incomplet va rămâne semnalat în rapoarte.')}</p>{/if}{/if}
<footer>{#if step>1}<button class="button secondary" onclick={()=>step=step===3&&previous?1:step-1}><ChevronLeft size={16}/>{t('Назад','Înapoi')}</button>{/if}{#if step<3}<button class="button" onclick={next}>{t('Далее','Înainte')}<ChevronRight size={16}/></button>{:else}<button class="button" onclick={()=>void finish()}><Check size={16}/>{t('Выполнить','Execută')}</button>{/if}<button class="button secondary" onclick={onclose}><X size={16}/>{t('Закрыть','Închide')}</button></footer></div>
<style>.period-wizard{padding:22px;display:flex;flex-direction:column;gap:18px;min-height:100%;box-sizing:border-box}.period-wizard>label:not(.check-row){display:grid;grid-template-columns:240px minmax(0,1fr);gap:14px;align-items:center}fieldset{padding:18px;border:1px solid var(--border)}.danger{color:var(--danger,#db7272)}nav,footer{display:flex;gap:8px;justify-content:flex-end}nav button{display:flex;gap:6px;align-items:center;background:transparent;border:0;color:var(--text);padding:8px}footer{margin-top:auto}.table-wrap{min-height:180px}</style>
